// Простейший regex-детект ФИО и телефона (RU/EU). Не претендует на 100% полноту.
const item = $('Merge').first().json;
let text = item.raw_text || '';
const phoneRe = /(\+?\d[\d\s\-\(\)]{7,}\d)/g;
const nameRe = /\b([A-ZА-ЯЁ][a-zа-яё]+\s[A-ZА-ЯЁ][a-zа-яё]+)\b/g;
const phones = [...text.matchAll(phoneRe)].map(m => m[1]);
const names = [...text.matchAll(nameRe)].map(m => m[1]);
let sanitized = text;
phones.forEach(p => { sanitized = sanitized.split(p).join('[PHONE]'); });
names.forEach(n => { sanitized = sanitized.split(n).join('[NAME]'); });

// Детерминированный ref_token из chat_id — один и тот же гость всегда получает один и тот же
// токен, без похода в pii_registry за проверкой "уже есть или нет".
function simpleHash(str) {
  let h = 0;
  for (let i = 0; i < str.length; i++) { h = (Math.imul(31, h) + str.charCodeAt(i)) | 0; }
  return Math.abs(h).toString(36);
}
const ref_token = 'g_' + simpleHash(String(item.chat_id));

return [{ json: { ...item, sanitized_text: sanitized, detected_name: names[0] || null, detected_phone: phones[0] || null, ref_token } }];

