const item = $input.item.json;

const explicitEscalate = item.escalate === true;
const explicitReason = item.escalate_reason || null;
const routerEscalate = item.router_needs_escalation === true;

const criticDecision = item.decision || null;
const criticScore = item.score || null;
const criticReasoning = item.reasoning || null;
const criticRecommendation = item.recommendation || null;
const criticIteration = parseInt(String(item.iteration || '0').replace(/\D/g,''), 10) || 0;
const criticExhausted = criticDecision === 'REVISE_CONTENT' && criticIteration >= 2;

const finalText = item.final_reply_text || item.router_draft_reply || '';
const moneyRe = /(депозит|предоплат|возврат|refund|payment link|€\s?\d|stripe)/i;
const moneyMentioned = moneyRe.test(finalText);

const needsHuman = explicitEscalate || routerEscalate || moneyMentioned || criticExhausted;
const reasons = [
  explicitReason,
  criticExhausted ? 'system_error' : null,
  ...(item.router_escalation_reasons || [])
].filter(Boolean);

return [{ json: {
  needs_human: needsHuman,
  conversation_log_id: Date.now(),
  escalation_reasons: reasons,
  final_reply_text: finalText,
  ref_token: item.pii_ref_token,
  chat_id: item.pii_chat_id,
  channel: item.pii_channel,
  guest_message_sanitized: item.pii_sanitized_text,
  critic_decision: criticDecision,
  critic_score: criticScore,
  critic_reasoning: criticReasoning,
  critic_recommendation: criticRecommendation,
  critic_iteration: criticIteration
} }];

const item = $input.item.json;
let text = item.sanitized_text || '';
const phoneRe = /(\+?\d[\d\s\-\(\)]{7,}\d)/g;
const nameRe = /\b([A-ZА-ЯЁ][a-zа-яё]+\s[A-ZА-ЯЁ][a-zа-яё]+)\b/g;
text = text.replace(phoneRe, '[PHONE]').replace(nameRe, '[NAME]');
return [{ json: { ...item, sanitized_text: text } }];

