const draft = $json.draft_reply || $json.output || '';

const phoneRegex = /\+?\d[\d\s\-\(\)]{7,}\d/;
const emailRegex = /[\w.+-]+@[\w-]+\.[a-zA-Z]{2,}/;

const leaked = phoneRegex.test(draft) || emailRegex.test(draft);

return [{
  json: {
    ...$json,
    pii_leak_detected: leaked,
    escalate: leaked ? true : ($json.escalate || false),
    escalate_reason: leaked ? 'system_error' : ($json.escalate_reason || null)
  }
}];

const raw = $json.output || $json.text || '';

const decisionMatch = raw.match(/\[DECISION:([A-Z_]+)\]/);
const scoreMatch = raw.match(/ОЦЕНКА:\s*(.+)/);
const reasonMatch = raw.match(/ОБОСНОВАНИЕ:\s*(.+)/);
const recMatch = raw.match(/РЕКОМЕНДАЦИЯ:\s*(.+)/);

const decision = decisionMatch ? decisionMatch[1] : 'REVISE_CONTENT';
const passed = decision === 'APPROVE';

return [{
  json: {
    ...$json,
    passed,
    decision,
    score: scoreMatch ? scoreMatch[1].trim() : null,
    reasoning: reasonMatch ? reasonMatch[1].trim() : null,
    recommendation: recMatch ? recMatch[1].trim() : null
  }
}];

const item = $json;
const pii = $('Code: PII Detect (regex)').first().json;

const clean = v => (typeof v === 'string' && v.startsWith('=')) ? v.slice(1) : v;

const cleaned = {};
for (const key in item) cleaned[key] = clean(item[key]);

let text = cleaned.router_draft_reply || '';
if (pii.detected_name) text = text.split('[NAME]').join(pii.detected_name);
if (pii.detected_phone) text = text.split('[PHONE]').join(pii.detected_phone);

return [{ json: { ...cleaned, router_draft_reply: text } }];
